<?php
namespace App\Controllers\Admin;use App\Support\App;use App\Services\WalletService;
final class UserController{
 public function save():never{$admin=App::requireAdmin();$in=App::input();$db=App::db();$id=(int)($in['id']??0);if(!$id)App::json(['ok'=>false,'message'=>'User tidak valid'],422);$name=trim((string)($in['name']??''));$email=trim((string)($in['email']??''));$phone=preg_replace('/[^0-9+]/','',(string)($in['phone']??''));$level=(int)($in['level_id']??0);$role=in_array($in['role']??'user',['user','admin'],true)?$in['role']:'user';$status=in_array($in['status']??'active',['active','disabled'],true)?$in['status']:'active';if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||!$level)App::json(['ok'=>false,'message'=>'Nama, email dan level wajib valid'],422);try{$db->beginTransaction();$q=$db->prepare('SELECT id,balance FROM users WHERE id=? FOR UPDATE');$q->execute([$id]);$old=$q->fetch();if(!$old)throw new \RuntimeException('User tidak ditemukan');$db->prepare('UPDATE users SET name=?,email=?,phone=?,level_id=?,role=?,status=? WHERE id=?')->execute([$name,$email,$phone,$level,$role,$status,$id]);$target=(float)($in['balance']??$old['balance']);$delta=$target-(float)$old['balance'];if(abs($delta)>0.0001)WalletService::move($db,$id,$delta,'admin_adjustment','ADMIN-'.$admin['id'].'-USER-'.$id,'admin-adjust:'.$id.':'.bin2hex(random_bytes(8)));$pass=(string)($in['new_password']??'');if($pass!==''){if(strlen($pass)<8)throw new \InvalidArgumentException('Password baru minimal 8 karakter');$db->prepare('UPDATE users SET password=? WHERE id=?')->execute([password_hash($pass,PASSWORD_DEFAULT),$id]);}$db->commit();App::json(['ok'=>true]);}catch(\Throwable $e){if($db->inTransaction())$db->rollBack();if($e instanceof \PDOException&&($e->errorInfo[1]??0)==1062)App::json(['ok'=>false,'message'=>'Email sudah dipakai akun lain'],409);throw $e;}}
}